import { Group, PlaneGeometry, Mesh, Vector3 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3, random } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load the image texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const texturePromise = ctx.textureLoader.loadTexture(imageUrl);
  let loadedTexture = null;

  // Plane geometry (width, height – tuned to contain text + padding)
  const planeGeometry = new PlaneGeometry(4, 1.2);
  const material = new MeshBasicNodeMaterial();
  material.color.set('#0b0b10'); // surface fallback while texture loads
  const planeMesh = new Mesh(planeGeometry, material);
  planeMesh.position.z = -0.1; // behind text
  group.add(planeMesh);

  // When texture arrives, attach it with a subtle grain overlay
  texturePromise.then(tex => {
    loadedTexture = tex;
    const texNode = texture(tex, uv());
    const grain = random(uv().fract()).mul(0.02);
    material.colorNode = texNode.add(grain);
    material.needsUpdate = true;
  });

  // Create the "Pricing" text headline
  const textObj = ctx.fontAtlas.createText('Pricing', {
    fontSize: 96,
    color: '#e8ecf2', // paper
    align: 'center',
  });

  // Scale to hero height ~0.62 scene units (96px → 0.62 via assumed factor)
  const textScale = 0.0065;
  textObj.scale.set(textScale, textScale, textScale);
  textObj.position.z = 0.01;
  group.add(textObj);

  // No event handlers (static)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    material.colorNode = null;
    material.map = null;
    material.dispose();

    if (loadedTexture) loadedTexture.dispose();

    textObj.traverse(child => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });

    // Kill any GSAP timelines (none present)
  };

  return group;
}
